-- Aprenda se Divertindo · 120 · Trilha Policial · lote extra 20 (100 questões de todos os níveis)
-- Rode depois do 119-trilha-policial-19.sql. Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.
-- Números 11047 a 11146: 20 de cada nível (0 a 4), quase todas em forma de caso prático, conferidas contra o banco e o Simulado Desafio.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id": 11047, "materia": "pen", "nivel": 0, "enunciado": "Roberto viu um carro com a porta aberta e levou o som, sem ninguém perceber. O crime é:", "opcoes": ["Furto", "Roubo", "Dano", "Receptação"], "explicacao": "Subtração sem violência ou grave ameaça (art. 155 do CP)."}, {"id": 11048, "materia": "pen", "nivel": 0, "enunciado": "Sem querer, Lia esqueceu o ferro de passar ligado e causou um incêndio. Se houver crime, ele será:", "opcoes": ["Culposo", "Doloso", "Preterdoloso", "Impossível"], "explicacao": "Não houve intenção, mas houve descuido (art. 18, II, do CP)."}, {"id": 11049, "materia": "pen", "nivel": 0, "enunciado": "Caio contratou um matador para eliminar um desafeto, sem participar da execução. Caio:", "opcoes": ["Responde pelo homicídio", "Não responde por nada", "Responde só por ameaça", "Responde só por incitação ao crime"], "explicacao": "Quem manda cometer o crime concorre para ele (art. 29 do CP)."}, {"id": 11050, "materia": "pen", "nivel": 1, "enunciado": "Numa discussão, Vítor esfaqueou o braço do colega, que ficou mais de 30 dias sem poder trabalhar. A lesão é:", "opcoes": ["Grave", "Leve", "Gravíssima", "Culposa"], "explicacao": "Art. 129, § 1º, I, do CP: incapacidade para as ocupações habituais por mais de 30 dias."}, {"id": 11051, "materia": "pen", "nivel": 1, "enunciado": "Celso, já casado no civil, casou-se de novo, também no civil, com outra mulher. O crime é:", "opcoes": ["Bigamia", "Adultério", "Falsidade ideológica", "Estelionato"], "explicacao": "Art. 235 do CP. O adultério deixou de ser crime em 2005."}, {"id": 11052, "materia": "pen", "nivel": 1, "enunciado": "Durante um assalto, Lino só vigiava a rua enquanto o comparsa roubava a loja. Lino:", "opcoes": ["Responde pelo roubo", "Não responde por nada", "Responde só por ameaça", "Responde por favorecimento"], "explicacao": "Quem concorre de qualquer modo para o crime responde por ele (art. 29 do CP)."}, {"id": 11053, "materia": "pen", "nivel": 2, "enunciado": "Um servidor contou a um amigo um segredo que soube por causa do cargo, causando prejuízo. O crime é:", "opcoes": ["Violação de sigilo funcional", "Prevaricação", "Condescendência criminosa", "Peculato"], "explicacao": "Art. 325 do CP."}, {"id": 11054, "materia": "pen", "nivel": 2, "enunciado": "Para não ser preso, Rui empurrou e agrediu o policial que cumpria um mandado legal. O crime é:", "opcoes": ["Resistência", "Desobediência", "Desacato", "Favorecimento"], "explicacao": "Art. 329 do CP: opor-se à execução de ato legal, com violência ou ameaça ao funcionário."}, {"id": 11055, "materia": "pen", "nivel": 2, "enunciado": "Ana desviou pequenas quantias do caixa da loja em dias seguidos, sempre do mesmo modo. Pode ser aplicado o:", "opcoes": ["Crime continuado", "Concurso material obrigatório", "Crime habitual", "Crime impossível"], "explicacao": "Art. 71 do CP: a pena de um só crime é aumentada de 1/6 a 2/3."}, {"id": 11056, "materia": "pen", "nivel": 3, "enunciado": "Pedro, de 30 anos, furtou o celular do pai, de 50 anos, sem violência. Pelo art. 181 do CP, Pedro:", "opcoes": ["É isento de pena", "Tem a pena dobrada", "Responde por roubo", "Tem a pena reduzida de 1/3"], "explicacao": "Escusa absolutória. Ela não vale se a vítima tiver 60 anos ou mais, nem em crime com violência ou grave ameaça (art. 183)."}, {"id": 11057, "materia": "pen", "nivel": 3, "enunciado": "Davi escondeu o próprio carro e registrou falso roubo para receber o seguro. Contra a seguradora, ele comete:", "opcoes": ["Fraude para recebimento de seguro", "Furto de coisa comum entre os sócios", "Apropriação indébita", "Receptação"], "explicacao": "Art. 171, § 2º, V, do CP."}, {"id": 11058, "materia": "pen", "nivel": 3, "enunciado": "O crime se consuma quando nele se reúnem todos os elementos da definição legal. Isso está no artigo do CP sobre:", "opcoes": ["Crime consumado", "Desistência voluntária", "Crime impossível", "Arrependimento posterior"], "explicacao": "Art. 14, I, do CP."}, {"id": 11059, "materia": "pen", "nivel": 4, "enunciado": "Um crime com pena máxima de 4 anos prescreve, antes da sentença, em:", "opcoes": ["8 anos", "4 anos", "12 anos", "3 anos"], "explicacao": "Art. 109, IV, do CP: pena máxima acima de 2 e até 4 anos prescreve em 8 anos."}, {"id": 11060, "materia": "pen", "nivel": 4, "enunciado": "Entre as causas que interrompem o prazo da prescrição está:", "opcoes": ["O recebimento da denúncia", "O registro do boletim de ocorrência", "A abertura do inquérito policial", "A citação por edital do réu"], "explicacao": "Art. 117, I, do CP."}, {"id": 11061, "materia": "ppen", "nivel": 0, "enunciado": "Na delegacia, o servidor que registra os depoimentos e cuida dos autos do inquérito é o:", "opcoes": ["Escrivão de polícia", "Juiz de direito", "Promotor de justiça", "Defensor público"], "explicacao": "O escrivão formaliza os atos do inquérito."}, {"id": 11062, "materia": "ppen", "nivel": 0, "enunciado": "O promotor de justiça faz parte do:", "opcoes": ["Ministério Público", "Poder Judiciário", "Poder Legislativo", "Polícia Civil"], "explicacao": "O MP é instituição autônoma (art. 127 da Constituição)."}, {"id": 11063, "materia": "ppen", "nivel": 0, "enunciado": "A decisão em que o juiz condena ou absolve o réu no fim do processo é a:", "opcoes": ["Sentença", "Denúncia", "Portaria", "Citação"], "explicacao": "Arts. 381 e seguintes do CPP."}, {"id": 11064, "materia": "ppen", "nivel": 1, "enunciado": "No Juizado Especial Criminal, o acordo entre autor e vítima sobre a reparação do dano chama-se:", "opcoes": ["Composição civil dos danos", "Transação penal", "Suspensão condicional do processo", "Pronúncia"], "explicacao": "Art. 74 da Lei 9.099/1995: homologada, pode extinguir a punibilidade nos crimes de ação privada ou condicionada."}, {"id": 11065, "materia": "ppen", "nivel": 1, "enunciado": "No termo circunstanciado, o autor do fato que assume o compromisso de ir ao Juizado:", "opcoes": ["Não é preso nem paga fiança", "É preso em flagrante", "Paga fiança obrigatória", "Fica preso até a audiência marcada"], "explicacao": "Art. 69, parágrafo único, da Lei 9.099/1995."}, {"id": 11066, "materia": "ppen", "nivel": 1, "enunciado": "O ofendido que entra no processo de ação pública para ajudar o MP na acusação é o:", "opcoes": ["Assistente de acusação", "Querelante", "Perito", "Defensor"], "explicacao": "Art. 268 do CPP."}, {"id": 11067, "materia": "ppen", "nivel": 4, "enunciado": "Quando o tribunal julga procedente uma revisão criminal, ele NÃO pode:", "opcoes": ["Agravar a pena imposta", "Absolver o réu", "Anular o processo", "Reduzir a pena"], "explicacao": "Art. 626, parágrafo único, do CPP."}, {"id": 11068, "materia": "ppen", "nivel": 2, "enunciado": "Pedro está sendo ameaçado de prisão ilegal, mas ainda não foi preso. Ele pode pedir:", "opcoes": ["Habeas corpus preventivo", "Habeas data", "Revisão criminal", "Mandado de injunção"], "explicacao": "No habeas corpus preventivo, concede-se salvo-conduto (art. 660, § 4º, do CPP)."}, {"id": 11069, "materia": "ppen", "nivel": 4, "enunciado": "No CPP, os embargos de declaração servem para corrigir:", "opcoes": ["Obscuridade, ambiguidade, contradição ou omissão", "Erro na contagem da pena já cumprida pelo réu preso", "Prova ilícita juntada pelo MP", "Nulidade da citação por edital"], "explicacao": "Art. 382 e art. 619 do CPP: prazo de 2 dias."}, {"id": 11070, "materia": "ppen", "nivel": 3, "enunciado": "Na busca domiciliar com mandado, antes de entrar, os executores devem:", "opcoes": ["Mostrar e ler o mandado ao morador e pedir que abra a porta", "Entrar sem avisar ninguém, para garantir a surpresa da busca", "Esperar o morador sair de casa", "Chamar a imprensa para acompanhar"], "explicacao": "Art. 245 do CPP."}, {"id": 11071, "materia": "ppen", "nivel": 3, "enunciado": "Terminada a busca domiciliar, os executores devem lavrar:", "opcoes": ["Auto circunstanciado, com duas testemunhas presenciais", "Boletim simples, sem nenhuma assinatura de testemunhas", "Termo de declarações do vizinho", "Relatório final do inquérito"], "explicacao": "Art. 245, § 7º, do CPP."}, {"id": 11072, "materia": "ppen", "nivel": 4, "enunciado": "Na instrução, surge prova de uma circunstância do crime que não estava descrita na denúncia. Pelo art. 384 do CPP, há:", "opcoes": ["Mutatio libelli, com aditamento pelo MP", "Emendatio libelli, sem aditamento", "Nulidade absoluta do processo inteiro", "Absolvição sumária obrigatória do acusado"], "explicacao": "Na mutatio libelli, muda o fato; o MP deve aditar a denúncia."}, {"id": 11073, "materia": "ppen", "nivel": 4, "enunciado": "Sem mudar a descrição do fato na denúncia, o juiz dá a ele outra definição jurídica, ainda que com pena mais grave. Isso é a:", "opcoes": ["Emendatio libelli", "Mutatio libelli", "Revisão criminal", "Correição parcial"], "explicacao": "Art. 383 do CPP."}, {"id": 11074, "materia": "const", "nivel": 0, "enunciado": "Ana tem 17 anos e tirou o título de eleitor. Para ela, votar é:", "opcoes": ["Facultativo", "Obrigatório", "Proibido", "Pago"], "explicacao": "Art. 14, § 1º, II, \"c\", da Constituição: facultativo para maiores de 16 e menores de 18."}, {"id": 11075, "materia": "const", "nivel": 0, "enunciado": "Quem chefia o Poder Executivo do Estado da Bahia é o:", "opcoes": ["Governador", "Presidente da Assembleia", "Prefeito de Salvador", "Desembargador mais antigo"], "explicacao": "Art. 28 da Constituição."}, {"id": 11076, "materia": "const", "nivel": 1, "enunciado": "Cada estado elege, para o Senado Federal:", "opcoes": ["3 senadores", "2 senadores", "4 senadores", "1 senador"], "explicacao": "Art. 46, § 1º, da Constituição."}, {"id": 11077, "materia": "const", "nivel": 1, "enunciado": "A Constituição garante a liberdade de crença e o livre exercício dos:", "opcoes": ["Cultos religiosos", "Cargos políticos", "Monopólios privados", "Juízos de exceção"], "explicacao": "Art. 5º, VI, da Constituição."}, {"id": 11078, "materia": "const", "nivel": 2, "enunciado": "A criação de um novo estado, dividindo um já existente, depende de:", "opcoes": ["Plebiscito da população interessada e lei complementar", "Decreto do Presidente, sem nenhuma consulta à população", "Lei estadual, com aprovação do governador", "Decisão do STF, a pedido do estado"], "explicacao": "Art. 18, § 3º, da Constituição."}, {"id": 11079, "materia": "const", "nivel": 2, "enunciado": "Os Tribunais de Contas auxiliam, no controle externo, o Poder:", "opcoes": ["Legislativo", "Judiciário", "Executivo", "Moderador"], "explicacao": "Art. 71 da Constituição."}, {"id": 11080, "materia": "const", "nivel": 3, "enunciado": "É proibida medida provisória sobre:", "opcoes": ["Direito penal e processual penal", "Organização de ministérios do governo", "Crédito extraordinário", "Matéria tributária"], "explicacao": "Art. 62, § 1º, I, \"b\", da Constituição."}, {"id": 11081, "materia": "const", "nivel": 3, "enunciado": "Se não for convertida em lei, a medida provisória perde a eficácia em:", "opcoes": ["60 dias, prorrogáveis por mais 60", "30 dias, sem prorrogação", "120 dias, sem prorrogação", "90 dias, prorrogáveis por mais 30"], "explicacao": "Art. 62, §§ 3º e 7º, da Constituição."}, {"id": 11082, "materia": "const", "nivel": 4, "enunciado": "Por simetria com a Constituição Federal, a lei que cria cargos na Polícia Civil da Bahia é de iniciativa privativa do:", "opcoes": ["Governador", "Delegado-Geral", "Presidente da Assembleia", "Tribunal de Justiça"], "explicacao": "Art. 61, § 1º, II, \"a\", da Constituição, aplicado aos estados."}, {"id": 11083, "materia": "const", "nivel": 4, "enunciado": "As polícias penais foram incluídas no art. 144 da Constituição pela Emenda Constitucional:", "opcoes": ["104/2019", "45/2004", "19/1998", "132/2023"], "explicacao": "A EC 45 tratou da reforma do Judiciário, a EC 19 da reforma administrativa e a EC 132 da reforma tributária."}, {"id": 11084, "materia": "adm", "nivel": 0, "enunciado": "A Polícia Civil da Bahia, órgão do governo estadual, faz parte da Administração:", "opcoes": ["Direta", "Indireta", "Privada", "Federal"], "explicacao": "Órgãos não têm personalidade jurídica e integram a Administração direta."}, {"id": 11085, "materia": "adm", "nivel": 0, "enunciado": "O investigador que cumpre a escala de plantão definida pelo chefe está sujeito ao poder:", "opcoes": ["Hierárquico", "Regulamentar", "De polícia", "Normativo"], "explicacao": "O poder hierárquico organiza a relação de subordinação."}, {"id": 11086, "materia": "adm", "nivel": 1, "enunciado": "Uma autarquia, como o Detran, faz parte da Administração:", "opcoes": ["Indireta", "Direta", "Privada", "Concentrada"], "explicacao": "Autarquias têm personalidade jurídica própria (art. 37, XIX, da Constituição)."}, {"id": 11087, "materia": "adm", "nivel": 1, "enunciado": "Aprovado no concurso, o candidato é investido no cargo efetivo pelo ato de:", "opcoes": ["Nomeação", "Remoção", "Redistribuição", "Exoneração"], "explicacao": "A nomeação é a forma de provimento originário."}, {"id": 11088, "materia": "adm", "nivel": 2, "enunciado": "Quem cumpre todos os requisitos legais tem direito à licença para construir. Por isso, a licença é ato:", "opcoes": ["Vinculado", "Discricionário", "Precário", "Inexistente"], "explicacao": "Preenchidos os requisitos, a Administração deve concedê-la."}, {"id": 11089, "materia": "adm", "nivel": 2, "enunciado": "A autorização para fechar uma rua para uma festa de bairro é ato:", "opcoes": ["Discricionário e precário", "Vinculado e definitivo", "Nulo por natureza", "Exclusivo do Judiciário"], "explicacao": "Pode ser revogada a qualquer tempo, por conveniência."}, {"id": 11090, "materia": "adm", "nivel": 3, "enunciado": "Pela Lei 14.133/2021, o agente de contratação deve ser, preferencialmente:", "opcoes": ["Servidor efetivo ou empregado dos quadros permanentes", "Ocupante de cargo em comissão sem nenhum vínculo efetivo", "Empresa terceirizada contratada", "Qualquer cidadão indicado pelo prefeito"], "explicacao": "Art. 8º da Lei 14.133/2021."}, {"id": 11091, "materia": "adm", "nivel": 3, "enunciado": "Na desapropriação por utilidade pública, a indenização deve ser:", "opcoes": ["Prévia, justa e em dinheiro", "Paga em títulos, em 20 anos", "Paga só depois da obra", "Dispensada, por ser interesse público"], "explicacao": "Art. 5º, XXIV, da Constituição."}, {"id": 11092, "materia": "adm", "nivel": 4, "enunciado": "Pela Lei 9.784/1999, no processo administrativo, o interessado pode ser assistido por advogado:", "opcoes": ["Facultativamente, salvo quando a lei o exigir", "Obrigatoriamente, em qualquer caso e em qualquer fase", "Somente na fase de recurso", "Nunca, pois o processo é interno"], "explicacao": "Art. 3º, IV, da Lei 9.784/1999."}, {"id": 11093, "materia": "leg", "nivel": 0, "enunciado": "Bento chutou e machucou o cachorro do vizinho. Isso é:", "opcoes": ["Crime de maus-tratos a animais", "Só uma briga de vizinhos, sem crime", "Infração de trânsito", "Conduta permitida"], "explicacao": "Art. 32 da Lei 9.605/1998. Contra cão ou gato, a pena é maior (§ 1º-A)."}, {"id": 11094, "materia": "leg", "nivel": 0, "enunciado": "Jonas pichou o muro de uma escola pública. Pela Lei de Crimes Ambientais, isso é:", "opcoes": ["Crime", "Arte livre", "Só falta de educação", "Infração de trânsito"], "explicacao": "Art. 65 da Lei 9.605/1998."}, {"id": 11095, "materia": "leg", "nivel": 0, "enunciado": "Pelo Código de Trânsito, criança pequena deve viajar no carro:", "opcoes": ["Na cadeirinha adequada, no banco de trás", "No colo de um adulto, no banco da frente", "Solta no banco de trás", "No porta-malas"], "explicacao": "Art. 64 do CTB e normas do Contran."}, {"id": 11096, "materia": "leg", "nivel": 1, "enunciado": "Pela Lei Maria da Penha, o juiz pode obrigar o agressor a:", "opcoes": ["Manter distância mínima da vítima", "Mudar de cidade sempre que a vítima pedir", "Pagar fiança à vítima", "Casar-se com a vítima"], "explicacao": "Art. 22, III, \"a\", da Lei 11.340/2006."}, {"id": 11097, "materia": "leg", "nivel": 1, "enunciado": "Mário matou um tatu na mata, sem nenhuma autorização. Pela Lei 9.605/1998, isso é:", "opcoes": ["Crime contra a fauna", "Conduta permitida", "Só infração de trânsito", "Contravenção penal"], "explicacao": "Art. 29 da Lei 9.605/1998."}, {"id": 11098, "materia": "leg", "nivel": 1, "enunciado": "Pelo ECA, cada Conselho Tutelar é composto por:", "opcoes": ["5 membros escolhidos pela comunidade", "3 juízes nomeados pelo Tribunal de Justiça", "10 policiais indicados", "1 promotor de justiça"], "explicacao": "Art. 132 do ECA."}, {"id": 11099, "materia": "leg", "nivel": 4, "enunciado": "Pelo ECA, um adolescente de 15 anos que vai viajar sozinho para outra comarca precisa, em regra, de:", "opcoes": ["Autorização judicial", "Apenas o RG", "Nada, se tiver celular", "Autorização do Conselho Tutelar"], "explicacao": "Art. 83 do ECA (Lei 13.812/2019): menores de 16 anos desacompanhados precisam de autorização judicial, salvo as exceções legais."}, {"id": 11100, "materia": "leg", "nivel": 2, "enunciado": "Na Lei de Drogas, se o tráfico envolver criança ou adolescente, a pena:", "opcoes": ["Aumenta de 1/6 a 2/3", "Diminui pela metade", "Não se altera", "Vira contravenção"], "explicacao": "Art. 40, VI, da Lei 11.343/2006."}, {"id": 11101, "materia": "leg", "nivel": 2, "enunciado": "Gil tem porte de arma e foi flagrado armado e embriagado num bar. Pelo Estatuto do Desarmamento, ele:", "opcoes": ["Perde o porte", "Mantém o porte normalmente", "Recebe só advertência", "Tem o porte dobrado"], "explicacao": "Art. 10, § 2º, da Lei 10.826/2003."}, {"id": 11102, "materia": "leg", "nivel": 3, "enunciado": "No CTB, o crime de embriaguez ao volante (art. 306) tem pena de:", "opcoes": ["Detenção de 6 meses a 3 anos, multa e suspensão", "Reclusão de 5 a 8 anos, sem multa nem suspensão", "Detenção de 15 dias a 1 mês", "Apenas multa administrativa"], "explicacao": "Art. 306 do CTB."}, {"id": 11103, "materia": "leg", "nivel": 4, "enunciado": "Na Lei de Tortura, se o crime é cometido contra criança, gestante, pessoa com deficiência, adolescente ou maior de 60 anos, a pena:", "opcoes": ["Aumenta de 1/6 até 1/3", "Aumenta de 2/3", "É aplicada em dobro", "Não se altera"], "explicacao": "Art. 1º, § 4º, II, da Lei 9.455/1997."}, {"id": 11104, "materia": "leg", "nivel": 3, "enunciado": "Pela Lei Maria da Penha, a vítima deve ser notificada dos atos processuais sobre o agressor, especialmente:", "opcoes": ["Da entrada e da saída dele da prisão", "Do salário que ele recebe", "Das viagens de trabalho dele", "Dos novos relacionamentos e endereços dele"], "explicacao": "Art. 21 da Lei 11.340/2006."}, {"id": 11105, "materia": "leg", "nivel": 4, "enunciado": "Pela Lei 12.850/2013, quem impede ou embaraça a investigação de uma organização criminosa fica sujeito:", "opcoes": ["Às mesmas penas da organização criminosa", "Apenas a uma multa administrativa da polícia", "À metade da pena da organização", "A nenhuma pena, se for parente"], "explicacao": "Art. 2º, § 1º, da Lei 12.850/2013."}, {"id": 11106, "materia": "leg", "nivel": 4, "enunciado": "Pela Lei 9.605/1998 e pelo STF, a pessoa jurídica pode ser responsabilizada penalmente por crime ambiental?", "opcoes": ["Sim, mesmo que nenhuma pessoa física seja condenada", "Não, só as pessoas físicas, como os diretores, respondem", "Sim, mas só se o dono também for condenado", "Não, só cabe multa administrativa"], "explicacao": "Art. 225, § 3º, da Constituição e art. 3º da Lei 9.605/1998. STF, RE 548.181."}, {"id": 11107, "materia": "port", "nivel": 0, "enunciado": "Complete: \"Os peritos ____ ao local bem cedo.\"", "opcoes": ["chegaram", "chegou", "chegamos", "chegará"], "explicacao": "Sujeito no plural: \"chegaram\"."}, {"id": 11108, "materia": "port", "nivel": 0, "enunciado": "Complete: \"Nós ____ o relatório ontem.\"", "opcoes": ["entregamos", "entregou", "entregaram", "entregarei"], "explicacao": "Sujeito \"nós\" no passado: \"entregamos\"."}, {"id": 11109, "materia": "port", "nivel": 1, "enunciado": "Um sinônimo de \"célere\", como em \"investigação célere\", é:", "opcoes": ["rápida", "lenta", "secreta", "difícil"], "explicacao": "Célere significa veloz, rápido."}, {"id": 11110, "materia": "port", "nivel": 1, "enunciado": "Complete: \"Depois da tempestade, a ____ alagou a rua da delegacia.\"", "opcoes": ["enxurrada", "enchurrada", "inxurrada", "enxurada"], "explicacao": "Depois de \"en\", usa-se \"x\": enxurrada, enxame, enxada."}, {"id": 11111, "materia": "port", "nivel": 2, "enunciado": "A palavra \"infelizmente\" é formada por:", "opcoes": ["Prefixo e sufixo", "Composição por justaposição de palavras", "Composição por aglutinação", "Redução"], "explicacao": "In- + feliz + -mente: derivação prefixal e sufixal."}, {"id": 11112, "materia": "port", "nivel": 2, "enunciado": "Assinale a frase em que \"aonde\" está empregado corretamente:", "opcoes": ["Aonde você vai com a viatura?", "Aonde fica a delegacia?", "A sala aonde guardam provas.", "Aonde ele mora hoje?"], "explicacao": "\"Aonde\" se usa com verbos de movimento que pedem \"a\" (ir a)."}, {"id": 11113, "materia": "port", "nivel": 3, "enunciado": "Em \"Precisa-se de investigadores experientes\", o \"se\" é:", "opcoes": ["Índice de indeterminação do sujeito", "Pronome apassivador do verbo transitivo", "Pronome reflexivo", "Conjunção condicional"], "explicacao": "Verbo com preposição (precisar de) + se: sujeito indeterminado, verbo no singular."}, {"id": 11114, "materia": "port", "nivel": 3, "enunciado": "Assinale a frase em que a expressão está correta:", "opcoes": ["Estudou a fim de passar no concurso.", "Estudou afim de passar no concurso.", "Os dois têm ideias a fim.", "Ele é a fim de ideias novas."], "explicacao": "\"A fim de\" indica finalidade; \"afim\" significa semelhante ou afinidade."}, {"id": 11115, "materia": "port", "nivel": 4, "enunciado": "Em \"Quanto mais o investigador estudava, mais aprendia\", há relação de:", "opcoes": ["Proporção", "Concessão", "Finalidade", "Condição"], "explicacao": "\"Quanto mais... mais\" indica proporcionalidade."}, {"id": 11116, "materia": "port", "nivel": 4, "enunciado": "Assinale a frase em que o uso do acento grave (crase) é facultativo:", "opcoes": ["Entreguei o relatório à minha chefe.", "Fui à delegacia de manhã.", "Chegou às duas horas.", "Referiu-se àquela testemunha do processo."], "explicacao": "Antes de pronome possessivo feminino singular, a crase é facultativa."}, {"id": 11117, "materia": "inf", "nivel": 0, "enunciado": "Chegou um e-mail de remetente desconhecido com um anexo estranho. O mais seguro é:", "opcoes": ["Apagar sem abrir o anexo", "Abrir o anexo para ver", "Encaminhar para os amigos", "Responder com seus dados"], "explicacao": "Anexos suspeitos podem conter vírus."}, {"id": 11118, "materia": "inf", "nivel": 1, "enunciado": "A sigla URL refere-se ao:", "opcoes": ["Endereço de uma página na internet", "Tipo de vírus de computador", "Programa de edição de texto e planilhas", "Cabo de rede do computador"], "explicacao": "Exemplo: https://aprendasedivertindo.com.br."}, {"id": 11119, "materia": "inf", "nivel": 2, "enunciado": "Guardar uma cópia de segurança fora do prédio da delegacia protege principalmente contra:", "opcoes": ["Incêndio, furto ou desastre no local", "Erros de digitação nos laudos periciais", "Lentidão da internet", "Falta de papel na impressora"], "explicacao": "Se o prédio for atingido, a cópia externa continua disponível."}, {"id": 11120, "materia": "inf", "nivel": 2, "enunciado": "O golpe de phishing feito por mensagem de SMS é chamado de:", "opcoes": ["Smishing", "Spoofing", "Sniffing", "Spam"], "explicacao": "Smishing = SMS + phishing."}, {"id": 11121, "materia": "inf", "nivel": 3, "enunciado": "No Windows, as teclas Ctrl + Shift + Esc abrem o:", "opcoes": ["Gerenciador de Tarefas", "Explorador de Arquivos", "Painel de Controle", "Bloco de Notas"], "explicacao": "Mostra os programas e processos em execução."}, {"id": 11122, "materia": "inf", "nivel": 4, "enunciado": "No Excel, com A1 = 6 e B1 = 4, a fórmula =SE(E(A1>5;B1>5);\"OK\";\"NÃO\") retorna:", "opcoes": ["NÃO", "OK", "FALSO", "#VALOR!"], "explicacao": "A função E só é verdadeira se as duas condições forem; B1 > 5 é falso."}, {"id": 11123, "materia": "rl", "nivel": 0, "enunciado": "Uma caixa tem 12 munições. Em 5 caixas iguais há:", "opcoes": ["60 munições", "17 munições", "50 munições", "72 munições"], "explicacao": "12 × 5 = 60."}, {"id": 11124, "materia": "rl", "nivel": 1, "enunciado": "Ana é mais alta que Bia, e Bia é mais alta que Cris. Logo:", "opcoes": ["Ana é mais alta que Cris", "Cris é mais alta que Ana", "Bia é a mais alta", "Ana e Cris têm a mesma altura"], "explicacao": "A relação \"mais alto que\" é transitiva."}, {"id": 11125, "materia": "rl", "nivel": 2, "enunciado": "Quantos anagramas tem a palavra BALA?", "opcoes": ["12", "24", "6", "4"], "explicacao": "4 letras com o A repetido 2 vezes: 4! ÷ 2! = 12."}, {"id": 11126, "materia": "rl", "nivel": 2, "enunciado": "Uma viatura de R$ 200 mil teve desconto de 15%. O valor final ficou em:", "opcoes": ["R$ 170 mil", "R$ 185 mil", "R$ 150 mil", "R$ 230 mil"], "explicacao": "15% de 200 mil = 30 mil; 200 − 30 = 170 mil."}, {"id": 11127, "materia": "rl", "nivel": 3, "enunciado": "Uma equipe faz 40 abordagens em 5 horas. Mantido o ritmo, em 8 horas fará:", "opcoes": ["64 abordagens", "48 abordagens", "45 abordagens", "80 abordagens"], "explicacao": "40 ÷ 5 = 8 por hora; 8 × 8 = 64."}, {"id": 11128, "materia": "rl", "nivel": 4, "enunciado": "Numa reunião com 7 agentes, cada um cumprimenta todos os outros uma única vez. O total de apertos de mão é:", "opcoes": ["21", "42", "14", "49"], "explicacao": "C(7,2) = 7 × 6 ÷ 2 = 21."}, {"id": 11129, "materia": "dh", "nivel": 0, "enunciado": "Os direitos humanos protegem as pessoas, principalmente, contra abusos do:", "opcoes": ["Estado", "Vizinho", "Mercado", "Clima"], "explicacao": "Eles limitam o poder estatal e também exigem ações do Estado."}, {"id": 11130, "materia": "dh", "nivel": 1, "enunciado": "O Pacto Internacional dos Direitos Civis e Políticos foi adotado no âmbito da:", "opcoes": ["ONU", "OEA", "OTAN", "OMC"], "explicacao": "Faz parte da chamada Carta Internacional de Direitos Humanos, com a Declaração Universal."}, {"id": 11131, "materia": "dh", "nivel": 2, "enunciado": "A Declaração Universal dos Direitos Humanos foi proclamada logo depois da:", "opcoes": ["Segunda Guerra Mundial", "Primeira Guerra Mundial", "Guerra Fria", "Revolução Francesa"], "explicacao": "Foi aprovada em 1948, em reação às atrocidades da guerra."}, {"id": 11132, "materia": "dh", "nivel": 3, "enunciado": "O Protocolo de Palermo, da ONU, trata principalmente do combate ao:", "opcoes": ["Tráfico de pessoas", "Desmatamento", "Trabalho noturno", "Analfabetismo"], "explicacao": "Protocolo adicional à Convenção contra o Crime Organizado Transnacional."}, {"id": 11133, "materia": "dh", "nivel": 4, "enunciado": "Em caso de grave violação de direitos humanos, o Procurador-Geral da República pode pedir ao STJ o deslocamento do caso para a:", "opcoes": ["Justiça Federal", "Justiça Militar", "Justiça Eleitoral", "Justiça do Trabalho"], "explicacao": "Art. 109, § 5º, da Constituição: incidente de deslocamento de competência."}, {"id": 11134, "materia": "ml", "nivel": 0, "enunciado": "Comparar o DNA de uma amostra encontrada no local com o de um suspeito serve para:", "opcoes": ["Identificar quem deixou a amostra", "Saber a hora exata em que o crime ocorreu", "Descobrir a arma usada", "Calcular a pena do réu"], "explicacao": "É a identificação genética."}, {"id": 11135, "materia": "ml", "nivel": 1, "enunciado": "Rigidez, resfriamento e livores são fenômenos:", "opcoes": ["Cadavéricos", "Vitais", "Digestivos", "Respiratórios"], "explicacao": "Ocorrem após a morte e ajudam a estimar o tempo de morte."}, {"id": 11136, "materia": "ml", "nivel": 2, "enunciado": "A mancha roxa na pele, por rompimento de pequenos vasos, sem corte, é a:", "opcoes": ["Equimose", "Escoriação", "Ferida incisa", "Fratura"], "explicacao": "A escoriação é o arranhão que tira a camada superficial da pele."}, {"id": 11137, "materia": "ml", "nivel": 3, "enunciado": "No local de crime, o isolamento da área pela polícia serve para:", "opcoes": ["Preservar os vestígios até a chegada da perícia", "Facilitar a entrada de curiosos", "Liberar o trânsito mais rápido", "Permitir que a família limpe e organize todo o local"], "explicacao": "Art. 6º, I, do CPP e arts. 158-A e seguintes (cadeia de custódia)."}, {"id": 11138, "materia": "ml", "nivel": 4, "enunciado": "Uma lesão que causa a perda ou inutilização de um membro é classificada como lesão corporal:", "opcoes": ["Gravíssima", "Grave", "Leve", "Privilegiada"], "explicacao": "Art. 129, § 2º, III, do CP."}, {"id": 11139, "materia": "est", "nivel": 1, "enunciado": "A média dos números 2, 4 e 6 é:", "opcoes": ["4", "6", "12", "3"], "explicacao": "12 ÷ 3 = 4."}, {"id": 11140, "materia": "est", "nivel": 3, "enunciado": "Numa pesquisa, a variável \"bairro onde a vítima mora\" é:", "opcoes": ["Qualitativa nominal", "Quantitativa contínua", "Quantitativa discreta", "Qualitativa ordinal"], "explicacao": "Os bairros são categorias sem ordem natural."}, {"id": 11141, "materia": "est", "nivel": 4, "enunciado": "Num histograma com as idades dos presos de uma unidade, a classe com maior frequência é chamada de:", "opcoes": ["Classe modal", "Classe mediana", "Amplitude total", "Desvio padrão"], "explicacao": "É a classe onde está a moda."}, {"id": 11142, "materia": "cont", "nivel": 0, "enunciado": "Um empréstimo que a empresa pegou no banco e ainda precisa pagar fica no:", "opcoes": ["Passivo", "Ativo", "Patrimônio líquido", "Resultado"], "explicacao": "É uma obrigação com terceiros."}, {"id": 11143, "materia": "cont", "nivel": 2, "enunciado": "Um cliente pagou à empresa uma conta antiga, sem juros. Esse fato contábil é:", "opcoes": ["Permutativo", "Modificativo aumentativo", "Misto aumentativo", "Modificativo diminutivo"], "explicacao": "Entra dinheiro no caixa e sai o valor de clientes a receber: o PL não muda."}, {"id": 11144, "materia": "cont", "nivel": 3, "enunciado": "Na Demonstração do Resultado do Exercício (DRE), aparecem:", "opcoes": ["Receitas, custos e despesas do período", "Só os bens e direitos da empresa no fim do ano", "Só as dívidas com bancos", "O capital social dos sócios"], "explicacao": "A DRE mostra se houve lucro ou prejuízo."}, {"id": 11145, "materia": "igual", "nivel": 3, "enunciado": "A violência psicológica contra a mulher passou a ser crime no Código Penal, no artigo:", "opcoes": ["147-B", "121-A", "140, § 3º", "215-A"], "explicacao": "Incluído pela Lei 14.188/2021. O 121-A é o feminicídio e o 215-A a importunação sexual."}, {"id": 11146, "materia": "pcd", "nivel": 2, "enunciado": "Pela LBI, a pessoa com deficiência tem direito a atendimento prioritário, por exemplo:", "opcoes": ["Em órgãos públicos e no atendimento ao público em geral", "Somente em hospitais particulares conveniados ao SUS local", "Somente nos dias úteis à tarde", "Somente se pagar taxa"], "explicacao": "Art. 9º da Lei 13.146/2015."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes where id < 1000000));
select nivel, count(*) as questoes_novas from public.questoes where id between 11047 and 11146 group by nivel order by nivel;
select public.questoes_versao() as nova_versao;
